using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Abstractions.Slugs;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;using Dhole.Content.Domain.Taxonomies.Entities;namespace Dhole.Content.Application.Taxonomies.CreateTaxonomy;public sealed class CreateTaxonomyCommandHandler(ITaxonomyTermRepository repo,ISlugGenerator slugs,IContentAuditService audit,IUnitOfWork uow):ICommandHandler<CreateTaxonomyCommand,Result<Guid>>{public async Task<Result<Guid>> HandleAsync(CreateTaxonomyCommand c,CancellationToken ct=default){var site=string.IsNullOrWhiteSpace(c.SiteKey)?ContentConstants.DefaultSiteKey:c.SiteKey.Trim();var kind=string.Equals(c.Kind,"tag",StringComparison.OrdinalIgnoreCase)?ContentConstants.TagKind:ContentConstants.CategoryKind;var slug=string.IsNullOrWhiteSpace(c.Slug)?await slugs.GenerateUniqueAsync(c.Name,(candidate,token)=>repo.ExistsBySlugAsync(site,kind,candidate,null,token),ct):slugs.Generate(c.Slug);if(await repo.ExistsBySlugAsync(site,kind,slug,null,ct))return Result.Failure<Guid>(ContentErrors.TaxonomySlugAlreadyExists);var x=TaxonomyTerm.Create(kind,c.Name,slug,c.Description,c.ParentId,c.SortOrder,site,c.ActorUserId);await repo.AddAsync(x,ct);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.TaxonomyCreated,ContentAuditActions.Created,ContentAuditEntityTypes.TaxonomyTerm,x.Id,c.ActorUserId,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);return Result.Success(x.Id);}}
